import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import EvidenceUpload from "@/components/EvidenceUpload";
import { MapView } from "@/components/Map";
import { CoordinatesField } from "@/components/StoreLocationFields";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import MediaSpecializedOperationsPanel from "@/components/MediaSpecializedOperationsPanel";
import SearchableMultiSelect from "@/components/SearchableMultiSelect";
import { WorkspaceActions, WorkspaceHeader, WorkspaceShell } from "@/components/WorkspaceChrome";
import UrbanPointDetails from "./UrbanPointDetails";
import { useEffectivePermissions } from "@/hooks/useEffectivePermissions";
import { useListDensity } from "@/hooks/useListDensity";
import { trpc } from "@/lib/trpc";
import { ArrowLeft, Building2, CalendarClock, ChevronRight, ExternalLink, FileImage, History, MapPin, Megaphone, Plus, RadioTower, RefreshCw, RotateCcw, SlidersHorizontal, Truck, Upload, UserRound, Route, CalendarDays, CheckCircle2, XCircle } from "lucide-react";
import { FormEvent, useMemo, useState, type ComponentProps } from "react";
import { toast } from "sonner";
import { useLocation, useRoute } from "wouter";

type ChannelKind = "standard" | "external";
type PartnershipType = "paid" | "barter" | "mixed";
type ReplacementFrequency = "weekly" | "biweekly" | "monthly" | "quarterly" | "semiannual" | "annual" | "custom";
type MediaOperationCategory = "graphics" | "audio_video" | "leafleting" | "sound_car" | "influencers";
type PointPayload = { supplierId: number; cityId: number; mediaTypeId: number; mediaVariationTypeId: number | null; serviceTypeId: number | null; name: string; operationCategory: MediaOperationCategory; replacementFrequency: ReplacementFrequency | null; contractStartsOn: string | null; contractEndsOn: string | null; partnershipType: PartnershipType; address?: string; latitude: number | null; longitude: number | null; signalRangeKm: number | null; confirmReplaceExisting: boolean };
const operationCategoryMeta: Record<MediaOperationCategory, { title: string; description: string; channel: ChannelKind }> = {
  graphics: { title: "Mídia Urbana", description: "Planeje outdoors, painéis e demais superfícies urbanas com fornecedor, cobertura, vigência, evidências e debriefing.", channel: "standard" },
  audio_video: { title: "Mídia Audiovisual", description: "Controle rádios, TVs, horários de veiculação, alcance do sinal, comprovações e debriefing por fornecedor.", channel: "standard" },
  leafleting: { title: "Panfletagem", description: "Organize a distribuição territorial vinculada a campanhas, promoções, planos, setores e evidências de execução.", channel: "external" },
  sound_car: { title: "Carro de Som", description: "Acompanhe fornecedores, spots, dias, horários, rotas, rodagem e evidências de cada ativação.", channel: "external" },
  influencers: { title: "Influencers", description: "Planeje os pontos e campanhas vinculados às parcerias com influenciadores, posts e comprovações.", channel: "standard" },
};
const emptyPoint = { supplierId: "", cityId: "", mediaTypeId: "", mediaVariationTypeId: "", name: "", operationCategory: "graphics" as MediaOperationCategory, replacementFrequency: "" as ReplacementFrequency | "", contractStartsOn: "", contractEndsOn: "", partnershipType: "paid" as PartnershipType, address: "", latitude: "", longitude: "", signalRangeKm: "" };
const emptyCampaign = { tradeCampaignId: "", name: "", startsOn: "", endsOn: "", partnershipType: "paid" as PartnershipType, estimatedCost: "", notes: "", campaignDetails: "", rescheduleReason: "", dailyRate: "", circulationDays: "", dailyRoute: "", audioBrief: "", vehicleOperation: "", airingSchedule: "", activeSpotId: "", materialFormat: "", materialQuantity: "", deadlineDays: "", deliveryInstructions: "" };
const campaignStatusLabel: Record<string, string> = { active: "Ativa", inactive: "Inativa", scheduled: "Agendada", completed: "Encerrada", cancelled: "Cancelada" };
const partnershipLabel: Record<PartnershipType, string> = { paid: "Pago", barter: "Permuta", mixed: "Misto" };
function formatContractDate(value: string | null | undefined) { return value ? new Date(`${value.slice(0, 10)}T12:00:00`).toLocaleDateString("pt-BR") : null; }

export function SelectField({ label, children, value, onChange, disabled, id, className, ...props }: ComponentProps<"select"> & { label: string }) {
  return <label className="grid gap-1.5">
    <span className="text-xs font-medium text-muted-foreground">{label}</span>
    <select id={id ?? `media-select-${label.toLocaleLowerCase("pt-BR").replaceAll(/[^a-z0-9]+/g, "-")}`} value={value ?? ""} onChange={onChange} disabled={disabled} className={`h-10 w-full rounded-lg border border-border bg-background px-3 text-sm text-foreground outline-none transition focus-visible:ring-2 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 ${className ?? ""}`} {...props}>
      {children}
    </select>
  </label>;
}

function PointPreview({ coordinates, name }: { coordinates: string; name: string }) {
  const values = coordinates.split(/[,;\s]+/).filter(Boolean).map(Number);
  if (values.length !== 2 || !values.every(Number.isFinite)) return null;
  const center = { lat: values[0], lng: values[1] };
  return <div className="overflow-hidden rounded-xl border border-border md:col-span-2"><MapView className="h-56" initialCenter={center} initialZoom={16} onMapReady={map => { if (window.google?.maps?.marker?.AdvancedMarkerElement) new window.google.maps.marker.AdvancedMarkerElement({ map, position: center, title: name || "Novo ponto de mídia" }); else new window.google.maps.Marker({ map, position: center, title: name || "Novo ponto de mídia" }); }} /></div>;
}

function MediaDetailPage({ mediaPointId }: { mediaPointId: number }) {
  const [, setLocation] = useLocation();
  const { can } = useEffectivePermissions();
  const canWrite = can("media.write");
  const detail = trpc.media.pointDetails.useQuery({ mediaPointId });
  const point = detail.data;
  return <main className="mx-auto max-w-6xl space-y-5">
    <Button type="button" variant="outline" onClick={() => setLocation("/midias")} className="border-border"><ArrowLeft className="mr-1.5 h-4 w-4" />Voltar para mídias</Button>
    <header className="rounded-2xl border border-border bg-card p-5 shadow-sm"><p className="text-[11px] font-semibold uppercase tracking-[0.14em] text-primary">Ficha operacional de mídia</p><h1 className="mt-1 font-display text-3xl font-semibold text-foreground">{point?.name ?? "Detalhes da mídia"}</h1><p className="mt-2 text-sm text-muted-foreground">Fornecedor, cobertura, ciclos, histórico e evidências do ponto selecionado.</p></header>
    {detail.isLoading ? <div className="grid h-48 place-items-center rounded-2xl border border-border bg-card text-sm text-muted-foreground">Carregando detalhes...</div> : point ? <div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><aside className="space-y-4"><article className="rounded-xl bg-secondary p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><Building2 className="h-4 w-4 text-primary" />Cobertura e fornecedor</div><dl className="mt-4 space-y-3 text-sm"><div><dt className="text-xs text-muted-foreground">Fornecedor</dt><dd className="font-medium text-foreground">{point.supplierName}</dd></div><div><dt className="text-xs text-muted-foreground">Território</dt><dd className="font-medium text-foreground">{point.cityName} · {point.regionalName}</dd></div><div><dt className="text-xs text-muted-foreground">Tipo de mídia</dt><dd className="font-medium text-foreground">{point.mediaTypeName}{point.serviceTypeName ? ` · ${point.serviceTypeName}` : ""}</dd></div><div><dt className="text-xs text-muted-foreground">Localização</dt><dd className="font-medium text-foreground">{point.address || "Não informada"}</dd></div></dl></article><article className="rounded-xl border border-border bg-card p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><History className="h-4 w-4 text-primary" />Histórico</div><div className="mt-3 space-y-3">{point.history.length ? point.history.map(entry => <div key={`${entry.scope}-${entry.id}`} className="border-l-2 border-primary/30 pl-3"><p className="text-xs font-medium text-foreground">{entry.action === "schedule" ? "Veiculação agendada" : entry.action === "reschedule" ? "Veiculação reagendada" : entry.action === "create" ? "Registro criado" : "Atualização registrada"}</p><p className="mt-0.5 text-[11px] text-muted-foreground">{new Date(entry.occurredAt).toLocaleString("pt-BR")}</p></div>) : <p className="text-xs text-muted-foreground">Ainda não há alterações registradas.</p>}</div></article></aside><section className="overflow-hidden rounded-xl border border-border bg-card"><div className="border-b border-border px-4 py-3"><p className="text-sm font-semibold text-foreground">Veiculações e comprovações</p><p className="mt-0.5 text-xs text-muted-foreground">Toda programação e alteração permanece no histórico deste ponto.</p></div><div className="divide-y divide-border">{point.campaigns.length ? point.campaigns.map(campaign => <article key={campaign.id} className="p-4"><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-foreground">{campaign.name}</p><Badge className="border-0 bg-secondary text-[10px] text-foreground">{campaignStatusLabel[campaign.status] ?? campaign.status}</Badge><Badge className="border-0 bg-primary/10 text-[10px] text-primary">{partnershipLabel[campaign.partnershipType as PartnershipType]}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{new Date(`${campaign.startsOn}T12:00:00`).toLocaleDateString("pt-BR")} até {new Date(`${campaign.endsOn}T12:00:00`).toLocaleDateString("pt-BR")}</p>{campaign.campaignDetails && <p className="mt-2 text-xs leading-5 text-muted-foreground">{campaign.campaignDetails}</p>}{campaign.notes && <p className="mt-1 text-xs leading-5 text-muted-foreground">{campaign.notes}</p>}<div className="mt-3 flex flex-wrap gap-2">{campaign.evidences.map(evidence => <a key={evidence.id} href={evidence.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-[11px] font-medium text-foreground hover:bg-primary/10"><ExternalLink className="h-3 w-3" />{evidence.originalName}</a>)}</div><div className="mt-3"><EvidenceUpload entityType="media_campaign" entityId={campaign.id} regionalId={point.regionalId} canWrite={canWrite} /></div></article>) : <p className="p-5 text-sm text-muted-foreground">Nenhuma veiculação registrada para este ponto.</p>}</div></section></div> : <div className="rounded-2xl border border-border bg-card p-8 text-sm text-muted-foreground">Esta mídia não foi encontrada ou você não possui acesso a ela.</div>}
  </main>;
}

export default function MediaWorkspace({ initialChannel, initialCategory }: { initialChannel?: ChannelKind; initialCategory?: MediaOperationCategory }) {
  const [, setLocation] = useLocation();
  const [isDetailRoute, routeParams] = useRoute("/midias/:mediaPointId");
  const routeMediaPointId = isDetailRoute && routeParams?.mediaPointId ? Number(routeParams.mediaPointId) : null;
  const { can } = useEffectivePermissions();
  const { compact } = useListDensity();
  const canWrite = can("media.write");
  const utils = trpc.useUtils();
  const references = trpc.media.referenceData.useQuery();
  const tradeCampaigns = trpc.campaigns.list.useQuery();
  const categoryMeta = initialCategory ? operationCategoryMeta[initialCategory] : null;
  const [filters, setFilters] = useState({ regionalId: "", cityId: "", channelKind: initialChannel ?? categoryMeta?.channel ?? "", operationCategory: initialCategory ?? "", status: "", partnershipType: "" });
  const listInput = useMemo(() => ({ regionalId: filters.regionalId ? Number(filters.regionalId) : undefined, cityId: filters.cityId ? Number(filters.cityId) : undefined, channelKind: filters.channelKind ? filters.channelKind as ChannelKind : undefined, operationCategory: filters.operationCategory ? filters.operationCategory as MediaOperationCategory : undefined, status: filters.status ? filters.status as "active" | "inactive" | "scheduled" | "completed" | "cancelled" : undefined, partnershipType: filters.partnershipType ? filters.partnershipType as PartnershipType : undefined }), [filters]);
  const points = trpc.media.list.useQuery(listInput);
  const [showPointForm, setShowPointForm] = useState(false);
  const [showFilters, setShowFilters] = useState(false);
  const [campaignPointId, setCampaignPointId] = useState<number | null>(null);
  const [rescheduleCampaignId, setRescheduleCampaignId] = useState<number | null>(null);
  const detailPointId = null;
  const setDetailPointId = (id: number | null) => { if (id) setLocation(initialCategory === "audio_video" ? `/midias/tradicional/${id}` : `/midias/${id}`); };
  const [pointForm, setPointForm] = useState(emptyPoint);
  const [campaignForm, setCampaignForm] = useState(emptyCampaign);
  const [confirmReplaceOpen, setConfirmReplaceOpen] = useState(false);
  const [pendingPointPayload, setPendingPointPayload] = useState<PointPayload | null>(null);
  const [cityDistributions, setCityDistributions] = useState<Array<{ cityId: string; quantity: string; notes: string }>>([]);
  const [distributionDraft, setDistributionDraft] = useState({ cityId: "", quantity: "", notes: "" });
  const pointDetails = trpc.media.pointDetails.useQuery({ mediaPointId: detailPointId ?? 1 }, { enabled: detailPointId !== null });
  const invalidateMedia = () => { utils.media.list.invalidate(); utils.media.pointDetails.invalidate(); };
  const createPoint = trpc.media.createPoint.useMutation({ onSuccess: result => { toast.success(result.operationCategory === "audio_video" ? "Programa tradicional cadastrado." : "Ponto de mídia cadastrado."); invalidateMedia(); setShowPointForm(false); setPointForm(emptyPoint); setConfirmReplaceOpen(false); setPendingPointPayload(null); if (result.operationCategory === "audio_video") setLocation(`/midias/tradicional/${result.id}`); }, onError: error => { if (error.data?.code === "CONFLICT") { setConfirmReplaceOpen(true); return; } toast.error(error.message); } });
  const createCampaign = trpc.media.createCampaign.useMutation({ onSuccess: result => { toast.success(result.status === "scheduled" ? "Veiculação agendada com sucesso." : "Veiculação criada com sucesso."); invalidateMedia(); setCampaignPointId(null); setCampaignForm(emptyCampaign); }, onError: error => toast.error(error.message) });
  const createConfiguredCampaign = trpc.media.createConfiguredCampaign.useMutation({ onSuccess: result => { toast.success(result.status === "scheduled" ? "Veiculação agendada com configuração operacional." : "Veiculação criada com configuração operacional."); invalidateMedia(); setCampaignPointId(null); setCampaignForm(emptyCampaign); setCityDistributions([]); }, onError: error => toast.error(error.message) });
  const renewCampaign = trpc.media.renewCampaign.useMutation({ onSuccess: () => { toast.success("Veiculação reagendada e histórico preservado."); invalidateMedia(); setRescheduleCampaignId(null); setCampaignForm(emptyCampaign); }, onError: error => toast.error(error.message) });
  const submitPoint = (event: FormEvent) => { event.preventDefault(); const latitude = Number(pointForm.latitude.replace(",", ".")); const longitude = Number(pointForm.longitude.replace(",", ".")); const validCoordinates = Number.isFinite(latitude) && Number.isFinite(longitude); const payload: PointPayload = { supplierId: Number(pointForm.supplierId), cityId: Number(pointForm.cityId), mediaTypeId: Number(pointForm.mediaTypeId), mediaVariationTypeId: pointForm.mediaVariationTypeId ? Number(pointForm.mediaVariationTypeId) : null, serviceTypeId: null, name: pointForm.name, operationCategory: pointForm.operationCategory, replacementFrequency: pointForm.replacementFrequency || null, contractStartsOn: pointForm.contractStartsOn || null, contractEndsOn: pointForm.contractEndsOn || null, partnershipType: pointForm.partnershipType, address: pointForm.address || undefined, latitude: validCoordinates ? latitude : null, longitude: validCoordinates ? longitude : null, signalRangeKm: pointForm.operationCategory === "audio_video" && pointForm.signalRangeKm ? Number(pointForm.signalRangeKm.replace(",", ".")) : null, confirmReplaceExisting: false }; setPendingPointPayload(payload); createPoint.mutate(payload); };
  const submitCampaign = (event: FormEvent) => { event.preventDefault(); const payload = { name: campaignForm.name, startsOn: campaignForm.startsOn, endsOn: campaignForm.endsOn, partnershipType: campaignForm.partnershipType, estimatedCost: Number(campaignForm.estimatedCost || 0), notes: campaignForm.notes || undefined, campaignDetails: campaignForm.campaignDetails || undefined }; if (rescheduleCampaignId) renewCampaign.mutate({ sourceCampaignId: rescheduleCampaignId, ...payload, rescheduleReason: campaignForm.rescheduleReason || undefined }); else if (campaignPointId) createConfiguredCampaign.mutate({ mediaPointId: campaignPointId, tradeCampaignId: campaignForm.tradeCampaignId ? Number(campaignForm.tradeCampaignId) : null, ...payload, campaignConfig: { dailyRate: campaignForm.dailyRate ? Number(campaignForm.dailyRate) : undefined, circulationDays: campaignForm.circulationDays ? Number(campaignForm.circulationDays) : undefined, dailyRoute: campaignForm.dailyRoute || undefined, audioBrief: campaignForm.audioBrief || undefined, vehicleOperation: campaignForm.vehicleOperation || undefined, airingSchedule: campaignForm.airingSchedule || undefined, activeSpotId: campaignForm.activeSpotId ? Number(campaignForm.activeSpotId) : undefined, materialFormat: campaignForm.materialFormat || undefined, materialQuantity: campaignForm.materialQuantity ? Number(campaignForm.materialQuantity) : undefined, deadlineDays: campaignForm.deadlineDays ? Number(campaignForm.deadlineDays) : undefined, deliveryInstructions: campaignForm.deliveryInstructions || undefined }, cityDistributions: cityDistributions.map(item => ({ cityId: Number(item.cityId), quantity: Number(item.quantity), notes: item.notes || undefined })) }); };
  const openSchedule = (pointId: number) => { const point = points.data?.find(item => item.id === pointId); if (point?.operationCategory === "audio_video") { setLocation(`/midias/tradicional/${pointId}`); return; } if (point?.channelKind === "external") { setLocation(`/midias/externa/${pointId}`); return; } setLocation(`/midias/${pointId}?nova=1`); };
  const openPoint = (point: { id: number; operationCategory: string; channelKind?: string }) => { if (point.operationCategory === "audio_video") setLocation(`/midias/tradicional/${point.id}`); else if (point.channelKind === "external") setLocation(`/midias/externa/${point.id}`); else setDetailPointId(point.id); };
  const openReschedule = (campaign: { id: number; name: string; partnershipType: string; estimatedCost: string | number; notes: string | null; campaignDetails: string | null }) => { setCampaignPointId(null); setRescheduleCampaignId(campaign.id); setCampaignForm({ ...emptyCampaign, name: campaign.name, partnershipType: campaign.partnershipType as PartnershipType, estimatedCost: String(campaign.estimatedCost), notes: campaign.notes ?? "", campaignDetails: campaign.campaignDetails ?? "" }); };
  const resetFilters = () => setFilters({ regionalId: "", cityId: "", channelKind: initialChannel ?? categoryMeta?.channel ?? "", operationCategory: initialCategory ?? "", status: "", partnershipType: "" });
  const scheduledPoint = useMemo(() => points.data?.find(point => point.id === campaignPointId) ?? null, [campaignPointId, points.data]);
  const scheduledServiceName = scheduledPoint?.serviceTypeName?.toLocaleLowerCase("pt-BR") ?? "";
  const needsAudioVideoConfig = scheduledPoint?.operationCategory === "audio_video";
  const needsSoundTruckConfig = scheduledPoint?.operationCategory === "sound_car" || /carro.*som|som.*carro/.test(scheduledServiceName);
  const needsFlyerConfig = scheduledPoint?.operationCategory === "leafleting" || /panflet|folder|flyer/.test(scheduledServiceName);
  const availableDistributionCities = useMemo(() => {
    const usedCityIds = new Set(cityDistributions.map(item => Number(item.cityId)));
    return (references.data?.cities ?? []).filter(({ city }) => !usedCityIds.has(city.id));
  }, [cityDistributions, references.data?.cities]);
  const selectedSupplierId = Number(pointForm.supplierId || 0);
  const mediaTypes = references.data?.mediaTypes ?? [];
  const supplierMediaTypes = references.data?.supplierMediaTypes ?? [];
  const supplierCities = references.data?.supplierCities ?? [];
  const mediaTypesById = useMemo(() => new Map(mediaTypes.map(type => [type.id, type])), [mediaTypes]);
  const categoryMediaTypes = useMemo(() => mediaTypes.filter(type => type.operationCategory === pointForm.operationCategory), [mediaTypes, pointForm.operationCategory]);
  const eligibleSupplierIds = useMemo(() => {
    const citySupplierIds = pointForm.cityId ? new Set(supplierCities.filter(link => link.cityId === Number(pointForm.cityId)).map(link => link.supplierId)) : null;
    return new Set(supplierMediaTypes.filter(link => {
      const mediaType = mediaTypesById.get(link.mediaTypeId);
      return mediaType?.operationCategory === pointForm.operationCategory && (!pointForm.mediaTypeId || link.mediaTypeId === Number(pointForm.mediaTypeId)) && (!citySupplierIds || citySupplierIds.has(link.supplierId));
    }).map(link => link.supplierId));
  }, [mediaTypesById, pointForm.cityId, pointForm.mediaTypeId, pointForm.operationCategory, supplierCities, supplierMediaTypes]);
  const eligibleSuppliers = useMemo(() => (references.data?.suppliers ?? []).filter(supplier => eligibleSupplierIds.has(supplier.id)), [eligibleSupplierIds, references.data?.suppliers]);
  const availableMediaTypes = useMemo(() => categoryMediaTypes.filter(type => type.parentMediaTypeId === null && (!selectedSupplierId || supplierMediaTypes.some(link => link.supplierId === selectedSupplierId && link.mediaTypeId === type.id))), [categoryMediaTypes, selectedSupplierId, supplierMediaTypes]);
  const availableMediaVariations = useMemo(() => categoryMediaTypes.filter(type => type.parentMediaTypeId === Number(pointForm.mediaTypeId) && (!selectedSupplierId || supplierMediaTypes.some(link => link.supplierId === selectedSupplierId && link.mediaTypeId === type.id))), [categoryMediaTypes, pointForm.mediaTypeId, selectedSupplierId, supplierMediaTypes]);
  const addDistribution = () => { if (!distributionDraft.cityId || !distributionDraft.quantity) return; setCityDistributions(current => [...current, distributionDraft]); setDistributionDraft({ cityId: "", quantity: "", notes: "" }); };

  if (routeMediaPointId) return initialCategory === "graphics" || !initialCategory ? <UrbanPointDetails /> : <MediaDetailPage mediaPointId={routeMediaPointId} />;

  return <WorkspaceShell className={`space-y-6 ${compact ? "media-list-compact" : ""}`}>
    <WorkspaceHeader
      eyebrow="Trade"
      title={categoryMeta?.title ?? (initialChannel === "external" ? "Mídias externas" : "Mídias e campanhas")}
      description={categoryMeta?.description ?? (initialChannel === "external" ? "Controle carros de som, panfletagem e outras ativações externas com contratação, vigência, agenda, comprovações e histórico." : "Controle mídia tradicional e externa, contratação, vigência, agenda, comprovações e histórico por ponto de cobertura.")}
      icon={RadioTower}
      actions={<WorkspaceActions>
        {(initialCategory === "graphics" || initialCategory === "audio_video") && <Button type="button" variant="outline" onClick={() => setShowFilters(value => !value)} aria-expanded={showFilters}>
          <SlidersHorizontal />
          Filtros
        </Button>}
        {canWrite && <Button onClick={() => { setPointForm({ ...emptyPoint, operationCategory: initialCategory ?? "graphics" }); setShowPointForm(true); }}>
          <Plus />
          {initialCategory === "graphics" ? "Novo ponto de mídia urbana" : "Novo ponto de mídia"}
        </Button>}
      </WorkspaceActions>}
    />

    {showFilters && <section className="hub-filter-panel p-4 shadow-sm"><div className="flex flex-col gap-3 xl:flex-row xl:items-center"><div className="hub-filter-panel__label text-sm font-semibold text-foreground"><SlidersHorizontal className="h-4 w-4 text-primary" />Filtros</div><div className="grid flex-1 gap-3 sm:grid-cols-2 lg:grid-cols-5"><SearchableMultiSelect id="media-filter-regional" label="Regional" options={(references.data?.regionals ?? []).map(regional => ({ id: regional.id, label: regional.name }))} values={filters.regionalId ? [Number(filters.regionalId)] : []} onChange={values => setFilters({ ...filters, regionalId: values[0] ? String(values[0]) : "", cityId: "" })} maxSelections={1} placeholder="Todas" emptyMessage="Nenhuma regional disponível" /><SearchableMultiSelect id="media-filter-city" label="Cidade" options={(references.data?.cities ?? []).filter(item => !filters.regionalId || item.city.regionalId === Number(filters.regionalId)).map(({ city, regionalName }) => ({ id: city.id, label: city.name, description: regionalName }))} values={filters.cityId ? [Number(filters.cityId)] : []} onChange={values => setFilters({ ...filters, cityId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder="Todas" emptyMessage="Nenhuma cidade disponível" />{!initialCategory && <SearchableMultiSelect id="media-filter-channel" label="Canal" options={[{ id: 1, label: "Mídia" }, { id: 2, label: "Mídia externa" }]} values={filters.channelKind === "standard" ? [1] : filters.channelKind === "external" ? [2] : []} onChange={values => setFilters({ ...filters, channelKind: values[0] === 1 ? "standard" : values[0] === 2 ? "external" : "" })} maxSelections={1} placeholder="Todos" emptyMessage="Nenhum canal disponível" />}<SearchableMultiSelect id="media-filter-status" label="Situação" options={[{ id: 1, label: "Ativa", description: "active" }, { id: 2, label: "Inativa", description: "inactive" }, { id: 3, label: "Agendada", description: "scheduled" }, { id: 4, label: "Encerrada", description: "completed" }, { id: 5, label: "Cancelada", description: "cancelled" }]} values={["active", "inactive", "scheduled", "completed", "cancelled"].includes(filters.status) ? [["active", "inactive", "scheduled", "completed", "cancelled"].indexOf(filters.status) + 1] : []} onChange={values => setFilters({ ...filters, status: ["", "active", "inactive", "scheduled", "completed", "cancelled"][values[0] ?? 0] ?? "" })} maxSelections={1} placeholder="Todas" emptyMessage="Nenhuma situação disponível" /><SearchableMultiSelect id="media-filter-partnership" label="Modalidade" options={[{ id: 1, label: "Pago", description: "paid" }, { id: 2, label: "Permuta", description: "barter" }, { id: 3, label: "Misto", description: "mixed" }]} values={["paid", "barter", "mixed"].includes(filters.partnershipType) ? [["paid", "barter", "mixed"].indexOf(filters.partnershipType) + 1] : []} onChange={values => setFilters({ ...filters, partnershipType: ["", "paid", "barter", "mixed"][values[0] ?? 0] ?? "" })} maxSelections={1} placeholder="Todas" emptyMessage="Nenhuma modalidade disponível" /></div><div className="flex justify-end xl:items-center"><Button variant="outline" className="hub-filter-panel__reset border-border" onClick={resetFilters}>Redefinir filtros</Button></div></div></section>}

    {(initialCategory === "sound_car" || initialCategory === "influencers") && <MediaSpecializedOperationsPanel category={initialCategory} canWrite={canWrite} />}

    <section className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm"><div className="flex flex-col gap-3 border-b border-border px-5 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-display text-lg font-semibold text-foreground">Lista de mídias</p><p className="mt-0.5 text-xs text-muted-foreground">Clique em um item para abrir os dados completos, ciclos e evidências.</p></div><Badge variant="outline" className="w-fit border-border bg-secondary text-xs text-foreground">{points.data?.length ?? 0} pontos encontrados</Badge></div>{points.isLoading ? <div className="p-10 text-center text-sm text-muted-foreground">Carregando mídias...</div> : points.data?.length ? <div className="divide-y divide-border">{points.data.map(point => { const focusCampaign = point.activeCampaign ?? point.nextCampaign; return <article key={point.id} className="group grid gap-4 px-5 py-4 transition hover:bg-secondary/35 lg:grid-cols-[minmax(0,1.5fr)_minmax(230px,.8fr)_auto]"><button type="button" onClick={() => openPoint(point)} className="min-w-0 text-left"><div className="flex flex-wrap items-center gap-2">{point.coverImageUrl ? <img src={point.coverImageUrl} alt={`Identificação de ${point.name}`} className="h-11 w-11 rounded-lg border border-border bg-secondary object-cover" /> : <span className={`grid h-11 w-11 place-items-center rounded-lg ${point.channelKind === "external" ? "bg-orange-500/10 text-orange-600" : "bg-primary/10 text-primary"}`}>{point.channelKind === "external" ? <Truck className="h-4 w-4" /> : <Megaphone className="h-4 w-4" />}</span>}<div><p className="font-semibold text-foreground group-hover:text-primary">{point.name}</p><p className="mt-0.5 text-xs text-muted-foreground">{point.channelKind === "external" ? "Mídia externa" : "Mídia"} · {point.mediaTypeName}{point.serviceTypeName ? ` · ${point.serviceTypeName}` : ""}</p></div></div><p className="mt-3 flex items-center gap-1 text-xs text-muted-foreground"><Building2 className="h-3.5 w-3.5" />{point.supplierName}</p><p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground"><MapPin className="h-3.5 w-3.5" />{point.cityName} · {point.regionalName}</p><p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground"><CalendarDays className="h-3.5 w-3.5" />Vigência: {formatContractDate(point.contractStartsOn) ?? "sem início"}{point.contractEndsOn ? ` a ${formatContractDate(point.contractEndsOn)}` : " em aberto"}</p></button><button type="button" onClick={() => openPoint(point)} className="rounded-xl border border-border bg-background p-3 text-left transition hover:border-primary/40"><div className="flex items-center justify-between gap-2"><span className="text-[11px] font-semibold uppercase tracking-[.12em] text-muted-foreground">Veiculação atual</span><ChevronRight className="h-4 w-4 text-muted-foreground" /></div>{focusCampaign ? <><div className="mt-2 flex items-center gap-2">{point.coverImageUrl ? <img src={point.coverImageUrl} alt={`Arte de ${focusCampaign.name}`} className="h-10 w-10 shrink-0 rounded-lg border border-border object-cover" /> : <span className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary"><FileImage className="h-4 w-4" /></span>}<p className="min-w-0 truncate text-sm font-semibold text-foreground">{focusCampaign.name}</p></div><div className="mt-2 flex flex-wrap gap-1.5"><Badge className="border-0 bg-primary/10 text-[10px] text-primary">{campaignStatusLabel[focusCampaign.status] ?? focusCampaign.status}</Badge><Badge className="border-0 bg-secondary text-[10px] text-foreground">{partnershipLabel[focusCampaign.partnershipType as PartnershipType]}</Badge></div><p className="mt-2 text-xs text-muted-foreground">{new Date(`${focusCampaign.startsOn}T12:00:00`).toLocaleDateString("pt-BR")} — {new Date(`${focusCampaign.endsOn}T12:00:00`).toLocaleDateString("pt-BR")}</p>{initialCategory !== "graphics" && <><p className="mt-2 text-[11px] text-muted-foreground">Previsto: <strong className="text-foreground">{Number(focusCampaign.finance.estimatedAmount).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</strong> · Pago: <strong className="text-foreground">{Number(focusCampaign.finance.paidAmount).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</strong></p><p className="mt-1 text-[11px] text-muted-foreground">Saldo: <strong className={focusCampaign.finance.remainingAmount > 0 ? "text-orange-600" : "text-primary"}>{Number(focusCampaign.finance.remainingAmount).toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}</strong></p></>}</> : <p className="mt-2 text-sm text-muted-foreground">Sem veiculação programada</p>}</button><div className="flex items-center gap-2 lg:justify-end"><Button variant="outline" size="sm" onClick={() => openPoint(point)} className="h-9 rounded-lg border-border text-xs"><FileImage className="mr-1.5 h-3.5 w-3.5" />Detalhes</Button>{canWrite && <Button size="sm" onClick={() => openSchedule(point.id)} className="h-9 rounded-lg bg-primary text-xs hover:bg-primary/90"><CalendarClock className="mr-1.5 h-3.5 w-3.5" />Nova veiculação</Button>}</div></article>; })}</div> : <div className="p-12 text-center"><RadioTower className="mx-auto h-7 w-7 text-muted-foreground" /><p className="mt-3 text-sm font-semibold text-foreground">Nenhum ponto para estes filtros</p><p className="mt-1 text-xs text-muted-foreground">Ajuste os filtros ou registre uma nova mídia para iniciar o acompanhamento.</p></div>}</section>

    <Dialog open={detailPointId !== null} onOpenChange={open => { if (!open) setDetailPointId(null); }}><DialogContent className="max-h-[92vh] max-w-6xl overflow-y-auto"><DialogHeader><DialogTitle>{pointDetails.data?.name ?? "Detalhes da mídia"}</DialogTitle><DialogDescription>Fornecedor, cobertura, veiculações, contratação, histórico e comprovações do ponto selecionado.</DialogDescription></DialogHeader>{pointDetails.isLoading ? <div className="grid h-48 place-items-center text-sm text-muted-foreground">Carregando detalhes...</div> : pointDetails.data && <div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><aside className="space-y-4"><article className="rounded-xl bg-secondary p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><Building2 className="h-4 w-4 text-primary" />Cobertura e fornecedor</div><dl className="mt-4 space-y-3 text-sm"><div><dt className="text-xs text-muted-foreground">Fornecedor</dt><dd className="font-medium text-foreground">{pointDetails.data.supplierName}</dd></div><div><dt className="text-xs text-muted-foreground">Território</dt><dd className="font-medium text-foreground">{pointDetails.data.cityName} · {pointDetails.data.regionalName}</dd></div><div><dt className="text-xs text-muted-foreground">Tipo de mídia</dt><dd className="font-medium text-foreground">{pointDetails.data.mediaTypeName}{pointDetails.data.serviceTypeName ? ` · ${pointDetails.data.serviceTypeName}` : ""}</dd></div><div><dt className="text-xs text-muted-foreground">Localização</dt><dd className="font-medium text-foreground">{pointDetails.data.address || "Não informada"}</dd></div></dl></article><article className="rounded-xl border border-border p-4"><div className="flex items-center gap-2 text-sm font-semibold text-foreground"><History className="h-4 w-4 text-primary" />Histórico</div><div className="mt-3 space-y-3">{(pointDetails.data.history ?? []).length ? (pointDetails.data.history ?? []).map(entry => <div key={`${entry.scope}-${entry.id}`} className="border-l-2 border-primary/30 pl-3"><p className="text-xs font-medium text-foreground">{entry.action === "schedule" ? "Veiculação agendada" : entry.action === "reschedule" ? "Veiculação reagendada" : entry.action === "create" ? "Registro criado" : "Atualização registrada"}</p><p className="mt-0.5 text-[11px] text-muted-foreground">{new Date(entry.occurredAt).toLocaleString("pt-BR")}</p></div>) : <p className="text-xs text-muted-foreground">Ainda não há alterações registradas.</p>}</div></article></aside><section className="overflow-hidden rounded-xl border border-border"><div className="flex items-center justify-between gap-3 border-b border-border px-4 py-3"><div><p className="text-sm font-semibold text-foreground">Veiculações e comprovações</p><p className="mt-0.5 text-xs text-muted-foreground">Toda programação e alteração permanece no histórico deste ponto.</p></div>{canWrite && <Button size="sm" onClick={() => openSchedule(pointDetails.data!.id)} className="bg-primary text-xs hover:bg-primary/90"><Plus className="mr-1.5 h-3.5 w-3.5" />Nova veiculação</Button>}</div><div className="divide-y divide-border">{(pointDetails.data.campaigns ?? []).length ? (pointDetails.data.campaigns ?? []).map(campaign => <article key={campaign.id} className="p-4"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><p className="font-semibold text-foreground">{campaign.name}</p><Badge className="border-0 bg-secondary text-[10px] text-foreground">{campaignStatusLabel[campaign.status] ?? campaign.status}</Badge><Badge className="border-0 bg-primary/10 text-[10px] text-primary">{partnershipLabel[campaign.partnershipType as PartnershipType]}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{new Date(`${campaign.startsOn}T12:00:00`).toLocaleDateString("pt-BR")} até {new Date(`${campaign.endsOn}T12:00:00`).toLocaleDateString("pt-BR")}</p>{campaign.campaignDetails && <p className="mt-2 text-xs leading-5 text-muted-foreground">{campaign.campaignDetails}</p>}{campaign.notes && <p className="mt-1 text-xs leading-5 text-muted-foreground">{campaign.notes}</p>}</div>{canWrite && ["active", "scheduled"].includes(campaign.status) && <Button variant="outline" size="sm" className="h-8 border-border text-xs" onClick={() => openReschedule(campaign)}><RotateCcw className="mr-1.5 h-3.5 w-3.5" />Reagendar</Button>}</div><div className="mt-3 flex flex-wrap gap-2">{campaign.evidences.map(evidence => <a key={evidence.id} href={evidence.url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 rounded-md bg-secondary px-2 py-1 text-[11px] font-medium text-foreground hover:bg-primary/10"><ExternalLink className="h-3 w-3" />{evidence.originalName}</a>)}</div><div className="mt-3"><EvidenceUpload entityType="media_campaign" entityId={campaign.id} regionalId={pointDetails.data!.regionalId} canWrite={canWrite} /></div></article>) : <p className="p-5 text-sm text-muted-foreground">Nenhuma veiculação registrada para este ponto.</p>}</div></section></div>}</DialogContent></Dialog>

    <Dialog open={showPointForm} onOpenChange={setShowPointForm}><DialogContent className="max-h-[92vh] max-w-3xl overflow-y-auto"><DialogHeader><DialogTitle>{pointForm.operationCategory === "graphics" ? "Novo ponto de mídia urbana" : pointForm.operationCategory === "audio_video" ? "Novo programa de mídia tradicional" : "Novo ponto de mídia"}</DialogTitle><DialogDescription>Registre localização, contrato e ciclo de troca do ponto. As veiculações serão definidas na ficha operacional.</DialogDescription></DialogHeader><form onSubmit={submitPoint} className="grid gap-4 pt-2 md:grid-cols-2"><SearchableMultiSelect id="media-city" label="Cidade do ponto" options={(references.data?.cities ?? []).map(({ city, regionalName }) => ({ id: city.id, label: city.name, description: regionalName }))} values={pointForm.cityId ? [Number(pointForm.cityId)] : []} onChange={values => setPointForm({ ...pointForm, cityId: values[0] ? String(values[0]) : "", supplierId: "", mediaTypeId: "", mediaVariationTypeId: "" })} maxSelections={1} placeholder="Selecionar cidade" emptyMessage="Nenhuma cidade disponível" /><SearchableMultiSelect id="media-supplier" label="Fornecedor" disabled={!pointForm.cityId} options={eligibleSuppliers.map(supplier => ({ id: supplier.id, label: supplier.displayName, description: supplier.mainService || "Fornecedor de mídia" }))} values={pointForm.supplierId ? [Number(pointForm.supplierId)] : []} onChange={values => setPointForm({ ...pointForm, supplierId: values[0] ? String(values[0]) : "", mediaTypeId: "", mediaVariationTypeId: "" })} maxSelections={1} placeholder={pointForm.cityId ? "Selecionar fornecedor" : "Selecione a cidade primeiro"} emptyMessage="Nenhum fornecedor habilitado nesta categoria" /><SearchableMultiSelect id="media-type" label="Tipo de mídia" disabled={!selectedSupplierId} options={availableMediaTypes.map(type => ({ id: type.id, label: type.name, description: "Tipo principal disponível neste fornecedor" }))} values={pointForm.mediaTypeId ? [Number(pointForm.mediaTypeId)] : []} onChange={values => setPointForm({ ...pointForm, mediaTypeId: values[0] ? String(values[0]) : "", mediaVariationTypeId: "" })} maxSelections={1} placeholder={selectedSupplierId ? "Selecionar tipo de mídia" : "Selecione o fornecedor primeiro"} emptyMessage="Nenhum tipo de mídia vinculado ao fornecedor" />{pointForm.mediaTypeId && <SearchableMultiSelect id="media-variation" label="Subtipo de mídia" disabled={!availableMediaVariations.length} options={availableMediaVariations.map(type => ({ id: type.id, label: type.name, description: "Subtipo vinculado ao tipo de mídia" }))} values={pointForm.mediaVariationTypeId ? [Number(pointForm.mediaVariationTypeId)] : []} onChange={values => setPointForm({ ...pointForm, mediaVariationTypeId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder="Opcional: selecionar subtipo" emptyMessage="Nenhum subtipo cadastrado para este tipo" />}<label className="space-y-1.5"><Label htmlFor="media-name">Nome do ponto</Label><Input id="media-name" required value={pointForm.name} onChange={event => setPointForm({ ...pointForm, name: event.target.value })} placeholder="Ex.: Outdoor Av. Central" /></label><label className="space-y-1.5"><Label htmlFor="contract-start">Início do contrato</Label><Input id="contract-start" type="date" value={pointForm.contractStartsOn} onChange={event => setPointForm({ ...pointForm, contractStartsOn: event.target.value })} /></label><label className="space-y-1.5"><Label htmlFor="contract-end">Fim do contrato</Label><Input id="contract-end" type="date" value={pointForm.contractEndsOn} onChange={event => setPointForm({ ...pointForm, contractEndsOn: event.target.value })} /></label><SelectField label="Tipo de contrato" value={pointForm.partnershipType} onChange={event => setPointForm({ ...pointForm, partnershipType: event.target.value as PartnershipType })} required><option value="paid">Pago</option><option value="barter">Permuta</option><option value="mixed">Misto</option></SelectField><label className="space-y-1.5"><Label htmlFor="media-replacement-frequency">Período de troca</Label><select id="media-replacement-frequency" value={pointForm.replacementFrequency} onChange={event => setPointForm({ ...pointForm, replacementFrequency: event.target.value as ReplacementFrequency })} className="h-10 w-full rounded-lg border border-border bg-background px-3 text-sm text-foreground"><option value="">Não informado</option><option value="weekly">Semanal</option><option value="biweekly">Quinzenal</option><option value="monthly">Mensal</option><option value="quarterly">Trimestral</option><option value="semiannual">Semestral</option><option value="annual">Anual</option><option value="custom">Personalizado</option></select></label><label className="space-y-1.5 md:col-span-2"><Label htmlFor="media-address">Localização ou rota de referência</Label><Input id="media-address" value={pointForm.address} onChange={event => setPointForm({ ...pointForm, address: event.target.value })} placeholder="Endereço, fachada, sentido da via ou rota de referência" /></label><CoordinatesField latitude={pointForm.latitude} longitude={pointForm.longitude} setLatitude={latitude => setPointForm(current => ({ ...current, latitude }))} setLongitude={longitude => setPointForm(current => ({ ...current, longitude }))} className="md:col-span-2" />{pointForm.operationCategory === "audio_video" && <label className="space-y-1.5 md:col-span-2"><Label htmlFor="media-signal-range">Raio de alcance do sinal (km)</Label><Input id="media-signal-range" type="number" min="0" max="1000" step="0.1" value={pointForm.signalRangeKm} onChange={event => setPointForm({ ...pointForm, signalRangeKm: event.target.value })} placeholder="Ex.: 80" /><p className="text-xs text-muted-foreground">O mapa exibirá este raio ao redor da rádio ou emissora.</p></label>}<PointPreview coordinates={`${pointForm.latitude}, ${pointForm.longitude}`} name={pointForm.name} /><div className="flex justify-end md:col-span-2"><Button type="submit" disabled={createPoint.isPending || !selectedSupplierId || !pointForm.mediaTypeId || !pointForm.cityId} className="bg-primary hover:bg-primary/90">{createPoint.isPending ? <RefreshCw className="mr-2 h-4 w-4 animate-spin" /> : null}{pointForm.operationCategory === "audio_video" ? "Salvar programa" : "Salvar ponto"}</Button></div></form></DialogContent></Dialog>

    <AlertDialog open={confirmReplaceOpen} onOpenChange={open => { setConfirmReplaceOpen(open); if (!open) setPendingPointPayload(null); }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Já existe uma mídia neste local</AlertDialogTitle><AlertDialogDescription>Foi encontrado um ponto ativo na mesma localização. Se você continuar, a veiculação ativa anterior será encerrada e o ponto anterior ficará inativo antes do novo cadastro.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Manter a mídia anterior</AlertDialogCancel><AlertDialogAction disabled={createPoint.isPending || !pendingPointPayload} onClick={() => { if (pendingPointPayload) createPoint.mutate({ ...pendingPointPayload, confirmReplaceExisting: true }); }}>Encerrar anterior e criar nova</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
    <Dialog open={campaignPointId !== null || rescheduleCampaignId !== null} onOpenChange={open => { if (!open) { setCampaignPointId(null); setRescheduleCampaignId(null); setCityDistributions([]); } }}>
      <DialogContent className="max-h-[92vh] max-w-4xl overflow-y-auto">
        <DialogHeader><DialogTitle>{rescheduleCampaignId ? "Reagendar veiculação" : "Nova veiculação"}</DialogTitle><DialogDescription>{rescheduleCampaignId ? "Registre a nova vigência e os detalhes da substituição. O ciclo anterior será preservado no histórico." : "Defina a veiculação e seus parâmetros operacionais para acompanhamento completo."}</DialogDescription></DialogHeader>
	        <form onSubmit={submitCampaign} className="grid gap-4 pt-2 md:grid-cols-2">
	          <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-name">Nome da veiculação</Label><Input id="campaign-name" required value={campaignForm.name} onChange={event => setCampaignForm({ ...campaignForm, name: event.target.value })} placeholder="Ex.: Veiculação de setembro" /></label>
	          {!rescheduleCampaignId && <div className="md:col-span-2"><SearchableMultiSelect id="media-trade-campaign" label="Campanha comercial vinculada" options={(tradeCampaigns.data ?? []).map(campaign => ({ id: campaign.id, label: campaign.name, description: `${campaign.status === "active" ? "Ativa" : "Planejada"}${campaign.regionalName ? ` · ${campaign.regionalName}` : ""}` }))} values={campaignForm.tradeCampaignId ? [Number(campaignForm.tradeCampaignId)] : []} onChange={values => setCampaignForm({ ...campaignForm, tradeCampaignId: values[0] ? String(values[0]) : "" })} maxSelections={1} placeholder="Vincular a uma campanha (opcional)" emptyMessage="Nenhuma campanha comercial disponível" /></div>}
          <label className="space-y-1.5"><Label htmlFor="campaign-start">Início</Label><Input id="campaign-start" required type="date" value={campaignForm.startsOn} onChange={event => setCampaignForm({ ...campaignForm, startsOn: event.target.value })} /></label>
          <label className="space-y-1.5"><Label htmlFor="campaign-end">Término</Label><Input id="campaign-end" required type="date" value={campaignForm.endsOn} onChange={event => setCampaignForm({ ...campaignForm, endsOn: event.target.value })} /></label>
          <SearchableMultiSelect id="media-partnership" label="Modalidade de contratação" options={[{ id: 1, label: "Pago" }, { id: 2, label: "Permuta" }, { id: 3, label: "Misto" }]} values={[({ paid: 1, barter: 2, mixed: 3 } as const)[campaignForm.partnershipType]]} onChange={values => setCampaignForm({ ...campaignForm, partnershipType: ({ 1: "paid", 2: "barter", 3: "mixed" } as const)[values[0] as 1 | 2 | 3] ?? "paid" })} maxSelections={1} placeholder="Selecionar modalidade" emptyMessage="Nenhuma modalidade disponível" />
          <label className="space-y-1.5"><Label htmlFor="campaign-cost">Investimento previsto</Label><Input id="campaign-cost" required type="number" min="0" step="0.01" value={campaignForm.estimatedCost} onChange={event => setCampaignForm({ ...campaignForm, estimatedCost: event.target.value })} placeholder="0,00" /></label>
          <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-details">Detalhes da veiculação</Label><Textarea id="campaign-details" value={campaignForm.campaignDetails} onChange={event => setCampaignForm({ ...campaignForm, campaignDetails: event.target.value })} placeholder="Peças, entregas, contrapartidas, público, rota ou outros detalhes operacionais" /></label>
	          {!rescheduleCampaignId && needsAudioVideoConfig && <section className="grid gap-3 rounded-xl border border-primary/20 bg-primary/5 p-4 md:col-span-2"><div><p className="font-semibold text-foreground">Configuração de Áudio e Vídeo</p><p className="text-xs text-muted-foreground">Registre o funcionamento do veículo e a grade de veiculação neste ciclo.</p></div><label className="space-y-1.5"><Label>Como o veículo opera</Label><Textarea value={campaignForm.vehicleOperation} onChange={event => setCampaignForm({ ...campaignForm, vehicleOperation: event.target.value })} placeholder="Ex.: programa, praça atendida, formato de inserção e regras do veículo" /></label><label className="space-y-1.5"><Label>Horários de veiculação</Label><Textarea value={campaignForm.airingSchedule} onChange={event => setCampaignForm({ ...campaignForm, airingSchedule: event.target.value })} placeholder="Ex.: seg–sex, 07h15, 12h30 e 18h45; 3 inserções diárias" /></label></section>}
          {!rescheduleCampaignId && needsSoundTruckConfig && <section className="grid gap-3 rounded-xl border border-orange-200 bg-orange-50/70 p-4 md:col-span-2 dark:border-orange-900/60 dark:bg-orange-950/20"><div><p className="font-semibold text-foreground">Configuração de carro de som</p><p className="text-xs text-muted-foreground">Defina a rota, os dias de circulação, a diária e os áudios de campanha.</p></div><div className="grid gap-3 md:grid-cols-2"><label className="space-y-1.5"><Label>Quantidade de dias</Label><Input type="number" min="1" value={campaignForm.circulationDays} onChange={event => setCampaignForm({ ...campaignForm, circulationDays: event.target.value })} /></label><label className="space-y-1.5"><Label>Valor por diária</Label><Input type="number" min="0" step="0.01" value={campaignForm.dailyRate} onChange={event => setCampaignForm({ ...campaignForm, dailyRate: event.target.value })} /></label></div><label className="space-y-1.5"><Label>Rota e horários diários</Label><Textarea value={campaignForm.dailyRoute} onChange={event => setCampaignForm({ ...campaignForm, dailyRoute: event.target.value })} placeholder="Cidades, bairros, horários e período de circulação" /></label><label className="space-y-1.5"><Label>Briefing dos áudios</Label><Textarea value={campaignForm.audioBrief} onChange={event => setCampaignForm({ ...campaignForm, audioBrief: event.target.value })} placeholder="Versão, locução, CTA, vigência e instruções. Após salvar, anexe os áudios na campanha." /></label></section>}
          {!rescheduleCampaignId && needsFlyerConfig && <section className="grid gap-3 rounded-xl border border-sky-200 bg-sky-50/70 p-4 md:col-span-2 dark:border-sky-900/60 dark:bg-sky-950/20"><div><p className="font-semibold text-foreground">Configuração de panfletagem</p><p className="text-xs text-muted-foreground">Distribua o material por cidade para acompanhar a execução territorial.</p></div><div className="grid gap-3 md:grid-cols-3"><label className="space-y-1.5"><Label>Formato do material</Label><Input value={campaignForm.materialFormat} onChange={event => setCampaignForm({ ...campaignForm, materialFormat: event.target.value })} placeholder="Ex.: A5 frente e verso" /></label><label className="space-y-1.5"><Label>Quantidade total</Label><Input type="number" min="1" value={campaignForm.materialQuantity} onChange={event => setCampaignForm({ ...campaignForm, materialQuantity: event.target.value })} /></label><label className="space-y-1.5"><Label>Prazo (dias)</Label><Input type="number" min="0" value={campaignForm.deadlineDays} onChange={event => setCampaignForm({ ...campaignForm, deadlineDays: event.target.value })} /></label></div><label className="space-y-1.5"><Label>Instruções de distribuição</Label><Textarea value={campaignForm.deliveryInstructions} onChange={event => setCampaignForm({ ...campaignForm, deliveryInstructions: event.target.value })} placeholder="Público, locais, equipe, abordagem e critérios de entrega" /></label><div className="grid gap-3 rounded-lg border border-border bg-background/70 p-3 md:grid-cols-[1.4fr_.8fr_1.2fr_auto]"><SelectField label="Cidade" value={distributionDraft.cityId} onChange={event => setDistributionDraft({ ...distributionDraft, cityId: event.target.value })}><option value="">Selecionar</option>{availableDistributionCities.map(({ city, regionalName }) => <option key={city.id} value={city.id}>{city.name} · {regionalName}</option>)}</SelectField><label className="space-y-1.5"><Label>Quantidade</Label><Input type="number" min="1" value={distributionDraft.quantity} onChange={event => setDistributionDraft({ ...distributionDraft, quantity: event.target.value })} /></label><label className="space-y-1.5"><Label>Observação</Label><Input value={distributionDraft.notes} onChange={event => setDistributionDraft({ ...distributionDraft, notes: event.target.value })} placeholder="Ex.: centro e bairros" /></label><Button type="button" className="self-end" variant="outline" onClick={addDistribution} disabled={!distributionDraft.cityId || !distributionDraft.quantity}>Adicionar</Button></div>{cityDistributions.length ? <div className="space-y-2">{cityDistributions.map((distribution, index) => <div key={distribution.cityId} className="flex items-center justify-between rounded-lg border border-border bg-background px-3 py-2 text-sm"><span>{references.data?.cities.find(item => item.city.id === Number(distribution.cityId))?.city.name ?? "Cidade"}: <strong>{distribution.quantity}</strong> unidades{distribution.notes ? ` · ${distribution.notes}` : ""}</span><Button type="button" size="sm" variant="ghost" className="text-destructive" onClick={() => setCityDistributions(current => current.filter((_, itemIndex) => itemIndex !== index))}>Remover</Button></div>)}</div> : null}</section>}
          {rescheduleCampaignId && <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-reason">Motivo do reagendamento</Label><Textarea id="campaign-reason" value={campaignForm.rescheduleReason} onChange={event => setCampaignForm({ ...campaignForm, rescheduleReason: event.target.value })} placeholder="Ex.: renovação negociada com nova peça e prazo" /></label>}
          <label className="space-y-1.5 md:col-span-2"><Label htmlFor="campaign-notes">Observações internas</Label><Textarea id="campaign-notes" value={campaignForm.notes} onChange={event => setCampaignForm({ ...campaignForm, notes: event.target.value })} placeholder="Informações de acompanhamento interno" /></label>
          <div className="flex justify-end gap-2 md:col-span-2"><Button type="button" variant="outline" onClick={() => { setCampaignPointId(null); setRescheduleCampaignId(null); }}>Cancelar</Button><Button type="submit" disabled={createConfiguredCampaign.isPending || renewCampaign.isPending} className="bg-primary hover:bg-primary/90">{(createConfiguredCampaign.isPending || renewCampaign.isPending) && <RefreshCw className="mr-2 h-4 w-4 animate-spin" />}{rescheduleCampaignId ? "Confirmar reagendamento" : "Confirmar veiculação"}</Button></div>
        </form>
      </DialogContent>
    </Dialog>
  </WorkspaceShell>;
}
